-- Incremental private-only extension. Does not provision or modify any administrator.
create table if not exists public.afandi_dubai_events(event_id uuid primary key,event_kind text not null check(event_kind in('view_item','add_to_cart','begin_checkout')),visitor_hash text not null,session_hash text not null,product_id text references public.afandi_dubai_products(id),quantity integer,source text not null default 'direct',medium text not null default 'none',campaign text not null default '',created_at timestamptz not null default now(),check((event_kind='begin_checkout' and product_id is null and quantity is null) or(event_kind='view_item' and product_id is not null and quantity is null) or(event_kind='add_to_cart' and product_id is not null and quantity between 1 and 99)));
create index if not exists afd_events_time_kind_idx on public.afandi_dubai_events(created_at,event_kind);
create index if not exists afd_events_product_idx on public.afandi_dubai_events(product_id,created_at);
create table if not exists public.afandi_dubai_browser_preferences(visitor_hash text primary key,remember boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.afandi_dubai_order_preferences(order_id uuid primary key references public.afandi_dubai_orders(id),marketing_opt_in boolean not null default false,remember boolean not null default false,recorded_at timestamptz not null default now());
alter table public.afandi_dubai_settings add column if not exists funnel_started_at timestamptz;
do $$ declare n text;begin foreach n in array array['events','browser_preferences','order_preferences'] loop execute format('alter table public.%I enable row level security','afandi_dubai_'||n);execute format('revoke all on public.%I from public,anon,authenticated','afandi_dubai_'||n);execute format('grant select,insert,update,delete on public.%I to service_role','afandi_dubai_'||n);end loop;end $$;
create or replace function public.afandi_dubai_funnel_report(p_from timestamptz,p_to timestamptz) returns jsonb language sql stable security invoker set search_path='' as $$ with e as(select * from public.afandi_dubai_events where created_at>=p_from and created_at<p_to),v as(select * from public.afandi_dubai_visits where created_at>=p_from and created_at<p_to),products as(select product_id,count(*) filter(where event_kind='view_item') views,count(distinct visitor_hash) filter(where event_kind='view_item') viewers,count(*) filter(where event_kind='add_to_cart') add_actions,count(distinct visitor_hash) filter(where event_kind='add_to_cart') add_visitors,coalesce(sum(quantity) filter(where event_kind='add_to_cart'),0) added_units from e where product_id is not null group by product_id) select jsonb_build_object('coverage_start',(select funnel_started_at from public.afandi_dubai_settings where id),'visit_coverage_start',(select tracking_started_at from public.afandi_dubai_settings where id),'visitors',(select count(distinct visitor_hash) from v),'pageviews',(select count(*) from v),'view_item_visitors',(select count(distinct visitor_hash) from e where event_kind='view_item'),'add_to_cart_visitors',(select count(distinct visitor_hash) from e where event_kind='add_to_cart'),'checkout_visitors',(select count(distinct visitor_hash) from e where event_kind='begin_checkout'),'add_to_cart_actions',(select count(*) from e where event_kind='add_to_cart'),'checkout_actions',(select count(*) from e where event_kind='begin_checkout'),'recorded_orders',(select count(*) from public.afandi_dubai_orders where created_at>=p_from and created_at<p_to),'top_products',coalesce((select jsonb_agg(x order by x.views desc,x.viewers desc,x.id) from(select p.id,p.name_ar,p.name_en,s.views,s.viewers,s.add_actions,s.add_visitors,s.added_units from products s join public.afandi_dubai_products p on p.id=s.product_id order by s.views desc,s.viewers desc,p.id limit 50)x),'[]'::jsonb)); $$;
create or replace function public.afandi_dubai_customer_list(p_search text default '',p_offset integer default 0,p_sort text default 'recent') returns jsonb language sql stable security invoker set search_path='' as $$ with money as(select order_id,sum(amount_cents) cents from public.afandi_dubai_sales_ledger group by order_id),c as(select o.customer_phone phone,(array_agg(o.customer_name order by o.created_at desc,o.id))[1] name,count(*) order_count,count(*) filter(where o.status in('completed','refunded')) fulfilled_count,coalesce(sum(m.cents),0) net_sales_cents,min(o.created_at) first_order_at,max(o.created_at) last_order_at from public.afandi_dubai_orders o left join money m on m.order_id=o.id group by o.customer_phone),filtered as(select * from c where p_search='' or strpos(lower(name),lower(p_search))>0 or strpos(phone,p_search)>0),page as(select * from filtered order by case when p_sort='spend' then net_sales_cents end desc,case when p_sort='orders' then order_count end desc,last_order_at desc,phone limit 51 offset greatest(p_offset,0)) select jsonb_build_object('customers',coalesce((select jsonb_agg(x) from(select page.*,coalesce((select op.marketing_opt_in from public.afandi_dubai_orders o join public.afandi_dubai_order_preferences op on op.order_id=o.id where o.customer_phone=page.phone order by op.recorded_at desc,o.id limit 1),false) marketing_opt_in from page limit 50)x),'[]'::jsonb),'has_more',(select count(*)>50 from page),'next_offset',p_offset+50,'total',(select count(*) from filtered),'coverage_start',(select orders_started_at from public.afandi_dubai_settings where id),'identity_note','Grouped by customer-supplied phone; phone ownership is not verified.'); $$;
create or replace function public.afandi_dubai_customer_profile(p_phone text,p_from timestamptz,p_to timestamptz) returns jsonb language sql stable security invoker set search_path='' as $$ with all_orders as(select * from public.afandi_dubai_orders where customer_phone=p_phone),period_orders as(select * from all_orders where created_at>=p_from and created_at<p_to),ledger as(select l.* from public.afandi_dubai_sales_ledger l join all_orders o on o.id=l.order_id),fav as(select x->>'id' id,(array_agg(x->>'name_ar' order by o.created_at desc))[1] name_ar,(array_agg(x->>'name_en' order by o.created_at desc))[1] name_en,sum((x->>'quantity')::int) units,count(distinct o.id) orders_count,sum((x->>'line_total_cents')::int) line_total_cents from all_orders o cross join lateral jsonb_array_elements(o.lines)x where o.status='completed' group by x->>'id'),allowed_browsers as(select o.visitor_hash,min(op.recorded_at) consent_at from all_orders o join public.afandi_dubai_order_preferences op on op.order_id=o.id and op.remember join public.afandi_dubai_browser_preferences bp on bp.visitor_hash=o.visitor_hash and bp.remember group by o.visitor_hash) select case when not exists(select 1 from all_orders) then null else jsonb_build_object('phone',p_phone,'name',(select customer_name from all_orders order by created_at desc,id limit 1),'first_order_at',(select min(created_at) from all_orders),'last_order_at',(select max(created_at) from all_orders),'last_consented_site_visit',(select max(v.created_at) from public.afandi_dubai_visits v join allowed_browsers b using(visitor_hash) where v.created_at>=b.consent_at),'lifetime',jsonb_build_object('orders',(select count(*) from all_orders),'completed_orders',(select count(*) from all_orders where status='completed'),'net_sales_cents',(select coalesce(sum(amount_cents),0) from ledger)),'period',jsonb_build_object('orders',(select count(*) from period_orders),'submitted_value_cents',(select coalesce(sum(total_cents),0) from period_orders),'net_sales_cents',(select coalesce(sum(amount_cents),0) from ledger where created_at>=p_from and created_at<p_to)),'orders',coalesce((select jsonb_agg(x) from(select reference,status,total_cents,created_at,branch_id,fulfilment,lines,source,medium,campaign from period_orders order by created_at desc,id limit 100)x),'[]'::jsonb),'orders_truncated',(select count(*)>100 from period_orders),'favorites',coalesce((select jsonb_agg(x) from(select * from fav order by units desc,orders_count desc,id limit 20)x),'[]'::jsonb),'marketing_opt_in',coalesce((select op.marketing_opt_in from all_orders o join public.afandi_dubai_order_preferences op on op.order_id=o.id order by op.recorded_at desc,o.id limit 1),false),'coverage_start',(select orders_started_at from public.afandi_dubai_settings where id),'identity_note','Customer-supplied name/phone, not a verified identity. Only consented, remembered-browser visits can be associated.') end; $$;
-- Caller supplies a verified signed visitor hash, never a client-submitted phone lookup.
create or replace function public.afandi_dubai_reorder_products(p_visitor text) returns jsonb language sql stable security invoker set search_path='' as $$ with ranked as(select x->>'id' id,sum((x->>'quantity')::integer) score from public.afandi_dubai_orders o join public.afandi_dubai_order_preferences op on op.order_id=o.id and op.remember join public.afandi_dubai_browser_preferences bp on bp.visitor_hash=o.visitor_hash and bp.remember cross join lateral jsonb_array_elements(o.lines)x where o.visitor_hash=p_visitor and o.status='completed' group by x->>'id') select coalesce(jsonb_agg(x),'[]'::jsonb) from(select p.id,p.name_ar,p.name_en,p.category,p.price_cents,p.image_url from ranked r join public.afandi_dubai_products p on p.id=r.id where p.active and p.available order by r.score desc,p.id limit 6)x; $$;
do $$ declare sig text;begin for sig in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('afandi_dubai_funnel_report','afandi_dubai_customer_list','afandi_dubai_customer_profile','afandi_dubai_reorder_products') loop execute 'revoke all on function '||sig||' from public,anon,authenticated';execute 'grant execute on function '||sig||' to service_role';end loop;end $$;
